// Smart Parking Assistant
// Uses 2 HC-SR04 sensors to detect slot occupancy

const int TRIG1 = 2, ECHO1 = 3;
const int TRIG2 = 4, ECHO2 = 5;
const int GREEN1 = 6, RED1 = 7;
const int GREEN2 = 8, RED2 = 9;
const int BUZZER = 10;
const int OCCUPIED_CM = 10; // distance threshold in cm

long readDistance(int trig, int echo) {
  digitalWrite(trig, LOW);
  delayMicroseconds(2);
  digitalWrite(trig, HIGH);
  delayMicroseconds(10);
  digitalWrite(trig, LOW);
  long duration = pulseIn(echo, HIGH, 30000);
  return duration * 0.034 / 2;
}

void setup() {
  Serial.begin(9600);
  pinMode(TRIG1, OUTPUT); pinMode(ECHO1, INPUT);
  pinMode(TRIG2, OUTPUT); pinMode(ECHO2, INPUT);
  int leds[] = {GREEN1, RED1, GREEN2, RED2, BUZZER};
  for (int i = 0; i < 5; i++) pinMode(leds[i], OUTPUT);
}

void loop() {
  long d1 = readDistance(TRIG1, ECHO1);
  long d2 = readDistance(TRIG2, ECHO2);
  bool slot1 = (d1 > 0 && d1 < OCCUPIED_CM);
  bool slot2 = (d2 > 0 && d2 < OCCUPIED_CM);

  digitalWrite(RED1,   slot1 ? HIGH : LOW);
  digitalWrite(GREEN1, slot1 ? LOW  : HIGH);
  digitalWrite(RED2,   slot2 ? HIGH : LOW);
  digitalWrite(GREEN2, slot2 ? LOW  : HIGH);
  digitalWrite(BUZZER, (slot1 && slot2) ? HIGH : LOW);

  Serial.print("Slot1: "); Serial.print(d1); Serial.print("cm ");
  Serial.print("Slot2: "); Serial.println(d2);
  delay(500);
}

// Soil Moisture Monitor
// Alerts when soil is too dry

const int SENSOR_PIN = A0;
const int RED_LED = 8;
const int GREEN_LED = 9;
const int BUZZER = 10;
const int DRY_THRESHOLD = 600; // Adjust 0–1023 based on your sensor

void setup() {
  Serial.begin(9600);
  pinMode(RED_LED, OUTPUT);
  pinMode(GREEN_LED, OUTPUT);
  pinMode(BUZZER, OUTPUT);
}

void loop() {
  int moisture = analogRead(SENSOR_PIN);
  Serial.print("Moisture: ");
  Serial.println(moisture);

  if (moisture > DRY_THRESHOLD) {
    // Soil is dry
    digitalWrite(RED_LED, HIGH);
    digitalWrite(GREEN_LED, LOW);
    digitalWrite(BUZZER, HIGH);
    delay(200);
    digitalWrite(BUZZER, LOW);
    delay(800);
  } else {
    // Moisture OK
    digitalWrite(RED_LED, LOW);
    digitalWrite(GREEN_LED, HIGH);
    digitalWrite(BUZZER, LOW);
  }
  delay(1000);
}

// Water Tank Level Alert

const int TRIG = 9, ECHO = 10;
const int LED_GREEN = 4, LED_YELLOW = 5, LED_RED = 6, BUZZER = 7;
const float TANK_HEIGHT = 30.0; // cm — measure your actual tank

long getDistance() {
  digitalWrite(TRIG, LOW); delayMicroseconds(2);
  digitalWrite(TRIG, HIGH); delayMicroseconds(10);
  digitalWrite(TRIG, LOW);
  long dur = pulseIn(ECHO, HIGH, 30000);
  return dur * 0.034 / 2;
}

void setup() {
  Serial.begin(9600);
  pinMode(TRIG, OUTPUT); pinMode(ECHO, INPUT);
  int pins[] = {LED_GREEN, LED_YELLOW, LED_RED, BUZZER};
  for (int i = 0; i < 4; i++) pinMode(pins[i], OUTPUT);
}

void loop() {
  long dist = getDistance();
  if (dist == 0) { delay(500); return; } // sensor error
  float filled = ((TANK_HEIGHT - dist) / TANK_HEIGHT) * 100.0;
  filled = constrain(filled, 0, 100);

  Serial.print("Level: "); Serial.print(filled); Serial.println("%");

  digitalWrite(LED_GREEN,  filled >= 66 ? HIGH : LOW);
  digitalWrite(LED_YELLOW, (filled >= 33 && filled < 66) ? HIGH : LOW);
  digitalWrite(LED_RED,    filled < 33 ? HIGH : LOW);
  digitalWrite(BUZZER,     filled < 15 ? HIGH : LOW);
  delay(1000);
}

// Temperature & Humidity Monitor with I2C LCD
#include <DHT.h>
#include <LiquidCrystal_I2C.h>

#define DHTPIN 2
#define DHTTYPE DHT11
DHT dht(DHTPIN, DHTTYPE);
LiquidCrystal_I2C lcd(0x27, 16, 2); // try 0x3F if 0x27 doesn't work

const int WARN_LED = 8;
const float HIGH_TEMP = 35.0; // °C warning threshold

void setup() {
  Serial.begin(9600);
  dht.begin();
  lcd.init();
  lcd.backlight();
  pinMode(WARN_LED, OUTPUT);
  lcd.print("CircuitVision");
  lcd.setCursor(0, 1);
  lcd.print("Starting...");
  delay(2000);
}

void loop() {
  float humidity = dht.readHumidity();
  float temperature = dht.readTemperature();

  if (isnan(humidity) || isnan(temperature)) {
    lcd.clear();
    lcd.print("Sensor Error");
    Serial.println("DHT read failed");
    delay(2000);
    return;
  }

  lcd.clear();
  lcd.setCursor(0, 0);
  lcd.print("Temp: "); lcd.print(temperature, 1); lcd.print((char)223); lcd.print("C");
  lcd.setCursor(0, 1);
  lcd.print("Humi: "); lcd.print(humidity, 1); lcd.print("%");

  Serial.print("T: "); Serial.print(temperature);
  Serial.print(" H: "); Serial.println(humidity);

  digitalWrite(WARN_LED, temperature >= HIGH_TEMP ? HIGH : LOW);
  delay(2000);
}

// Touchless Smart Dustbin
#include <Servo.h>

const int TRIG = 2, ECHO = 3;
const int SERVO_PIN = 9;
const int OPEN_DISTANCE = 15; // cm — hand detection range
const int LID_DELAY = 3000;   // ms — how long lid stays open

Servo lidServo;

long getDistance() {
  digitalWrite(TRIG, LOW); delayMicroseconds(2);
  digitalWrite(TRIG, HIGH); delayMicroseconds(10);
  digitalWrite(TRIG, LOW);
  long dur = pulseIn(ECHO, HIGH, 30000);
  return dur * 0.034 / 2;
}

void setup() {
  Serial.begin(9600);
  pinMode(TRIG, OUTPUT); pinMode(ECHO, INPUT);
  lidServo.attach(SERVO_PIN);
  lidServo.write(0); // closed
  delay(500);
}

void loop() {
  long dist = getDistance();
  Serial.print("Distance: "); Serial.println(dist);

  if (dist > 0 && dist < OPEN_DISTANCE) {
    lidServo.write(90); // open
    delay(LID_DELAY);
    lidServo.write(0);  // close
    delay(500);
  }
  delay(100);
}

// Obstacle Detection Alert
// Buzzer beeps faster as object approaches

const int TRIG = 9, ECHO = 10;
const int BUZZER = 7, LED = 8;
const int ALERT_DIST = 30; // cm

long getDistance() {
  digitalWrite(TRIG, LOW); delayMicroseconds(2);
  digitalWrite(TRIG, HIGH); delayMicroseconds(10);
  digitalWrite(TRIG, LOW);
  long dur = pulseIn(ECHO, HIGH, 30000);
  return dur * 0.034 / 2;
}

void setup() {
  Serial.begin(9600);
  pinMode(TRIG, OUTPUT); pinMode(ECHO, INPUT);
  pinMode(BUZZER, OUTPUT); pinMode(LED, OUTPUT);
}

void loop() {
  long dist = getDistance();
  Serial.print("Dist: "); Serial.println(dist);

  if (dist > 0 && dist < ALERT_DIST) {
    digitalWrite(LED, HIGH);
    // Beep interval shortens as object gets closer
    int beepDelay = map(dist, 1, ALERT_DIST, 50, 500);
    digitalWrite(BUZZER, HIGH);
    delay(100);
    digitalWrite(BUZZER, LOW);
    delay(beepDelay);
  } else {
    digitalWrite(LED, LOW);
    digitalWrite(BUZZER, LOW);
    delay(200);
  }
}

// Smart Plant Care Monitor
#include <DHT.h>

#define DHTPIN 2
#define DHTTYPE DHT11
DHT dht(DHTPIN, DHTTYPE);

const int SOIL_PIN = A0;
const int LDR_PIN  = A1;
const int LED_MOISTURE = 5; // Red
const int LED_LIGHT    = 6; // Blue
const int LED_TEMP     = 7; // Yellow

const int DRY_THRESHOLD   = 600;
const int DARK_THRESHOLD  = 300;
const float HOT_THRESHOLD = 35.0;

void setup() {
  Serial.begin(9600);
  dht.begin();
  pinMode(LED_MOISTURE, OUTPUT);
  pinMode(LED_LIGHT, OUTPUT);
  pinMode(LED_TEMP, OUTPUT);
}

void loop() {
  int soilVal  = analogRead(SOIL_PIN);
  int lightVal = analogRead(LDR_PIN);
  float temp   = dht.readTemperature();
  float humi   = dht.readHumidity();

  bool needsWater = soilVal > DRY_THRESHOLD;
  bool needsLight = lightVal < DARK_THRESHOLD;
  bool tooHot     = !isnan(temp) && temp > HOT_THRESHOLD;

  digitalWrite(LED_MOISTURE, needsWater ? HIGH : LOW);
  digitalWrite(LED_LIGHT,    needsLight ? HIGH : LOW);
  digitalWrite(LED_TEMP,     tooHot     ? HIGH : LOW);

  Serial.print("Soil: ");  Serial.print(soilVal);
  Serial.print(" Light: "); Serial.print(lightVal);
  Serial.print(" Temp: ");  Serial.print(temp);
  Serial.print("°C Humi: "); Serial.print(humi);
  Serial.println("%");

  delay(2000);
}

// Water Usage Monitoring Prototype
#include <LiquidCrystal_I2C.h>

LiquidCrystal_I2C lcd(0x27, 16, 2);

const int FLOW_PIN = 2;
const int BUZZER = 8;
const float CALIBRATION = 7.5;   // pulses per litre for YF-S201
const float DAILY_LIMIT_L = 50.0;

volatile int pulseCount = 0;
float totalLitres = 0.0;
unsigned long lastCalc = 0;

void IRAM_ATTR countPulse() {
  pulseCount++;
}

void setup() {
  Serial.begin(9600);
  lcd.init(); lcd.backlight();
  pinMode(FLOW_PIN, INPUT_PULLUP);
  attachInterrupt(digitalPinToInterrupt(FLOW_PIN), countPulse, FALLING);
  pinMode(BUZZER, OUTPUT);
  lcd.print("Water Monitor");
  delay(2000);
}

void loop() {
  if (millis() - lastCalc >= 1000) {
    lastCalc = millis();
    noInterrupts();
    int pulseCopy = pulseCount;
    pulseCount = 0;
    interrupts();

    float flowRate = (pulseCopy / CALIBRATION); // L/min
    totalLitres += flowRate / 60.0;             // L per second

    lcd.clear();
    lcd.setCursor(0, 0);
    lcd.print("Flow: "); lcd.print(flowRate, 1); lcd.print(" L/m");
    lcd.setCursor(0, 1);
    lcd.print("Total: "); lcd.print(totalLitres, 2); lcd.print("L");

    Serial.print("Flow: "); Serial.print(flowRate);
    Serial.print(" L/min  Total: "); Serial.println(totalLitres);

    digitalWrite(BUZZER, totalLitres >= DAILY_LIMIT_L ? HIGH : LOW);
  }
}
